    },
    {
      "chord_quality": "min7",
      "function_role": "bebop-scale-dorian-variant",
      "narrative": "The dorian bebop scale is the prescribed scale for minor seventh chords: it is the dorian mode with a chromatic note added between the 3rd and 4th degrees. Coker identifies this as 'the perfect anachronism to the chord quality with which it is used; that is, a major third against a minor seventh chord' -- the added major 3rd directly contradicts the chord's minor quality, yet is '99% consistent with what we find in analyzing transcribed solos' (p. 33). Even a 3-4 note fragment containing this chromatic note implies bebop-scale use.",
      "source_principle_ids": [],
      "source_work_id": "coker-elements-jazz-language",
      "references": [
