      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "min7",
      "function_role": "pentatonic-generalization",
      "narrative": "A single C pentatonic scale covers A-7, D-7, and G-7 (among ten chord types total) with no collision tones: 'a C pentatonic scale (C, D, E, G, A) will fit C [major], F [major], Bb [major](+4), A-7, D-7, G-7, C7, G7(sus. 4), D7(sus. 4), and a Gb7 (+5, b9) with not one colliding [pitch]' (p. 45). This makes pentatonic generalization the safest harmonic generalization strategy available.",
      "source_principle_ids": [],
      "source_work_id": "coker-elements-jazz-language",
      "references": [
        {
          "source": "coker-elements-jazz-language",
          "citation": "chapter 9 p.45"
        }
