      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "min7",
      "function_role": "practice-regimen-ii-v-cells",
      "narrative": "Coker prescribes a targeted practice approach for 7-3 resolution work centered on the II-7 chord: 'practice them with exercise tracks and tunes on play-alongs that contain a large number of II-V cells' (p. 24). When using stereo play-alongs, he recommends turning off the piano channel to test effectiveness of 7-3 resolutions without chordal accompaniment, eventually practicing with no accompaniment at all.",
      "source_principle_ids": [],
      "source_work_id": "coker-elements-jazz-language",
